#pragma once
static const char setup_html_before[] = "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"pocket-nonce\" content=\"";
static const char setup_html_after[] = "\"><title>Connect Hermes Pocket</title>\n<style>\n:root{color-scheme:dark;--bg:#101c25;--panel:#1a2c39;--line:#365061;--ink:#f4f1e9;--muted:#b9cbd6;--mint:#9ce4ce}*{box-sizing:border-box}body{font:16px system-ui,sans-serif;max-width:480px;margin:auto;padding:24px 16px;background:var(--bg);color:var(--ink)}h1{font-size:28px;margin:8px 0}h2{font-size:20px;margin:0 0 12px}p,small{line-height:1.5;color:var(--muted)}section,details{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:16px;margin:16px 0}label{display:block;margin:16px 0 8px}input,textarea,select,button{width:100%;font:inherit;border-radius:8px;padding:12px;min-height:48px}input,textarea,select{background:#0c1922;color:#fff;border:1px solid #678091}button{background:var(--mint);color:#102820;border:0;font-weight:700;margin-top:12px;cursor:pointer}button.secondary{background:#2a4354;color:#fff}button:disabled{opacity:.6;cursor:default}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--mint);outline-offset:3px}summary{cursor:pointer;padding:8px 0;font-weight:700}small{display:block;margin-top:8px}.tag{color:var(--mint);font-size:12px;letter-spacing:2px}.message{white-space:pre-wrap;overflow-wrap:anywhere;color:#ffd1a3}.message:empty{display:none}#connection{color:var(--mint);font-weight:700}#profile-count,#netstatus,#session-status{font-size:14px}#profiles{list-style:none;padding:0;margin:0}#profiles li{border-top:1px solid var(--line);padding:12px 0;overflow-wrap:anywhere}#profiles strong{display:block}#profiles small{margin:4px 0}.actions{display:flex;flex-wrap:wrap;gap:8px}.actions button{flex:1 1 96px;width:auto;margin-top:8px}input[type=checkbox]{width:20px;min-height:20px;vertical-align:middle;margin-right:8px}footer{margin:24px 0 8px}textarea{resize:vertical}\n</style>\n<main><div class=\"tag\">HERMES POCKET / SETUP</div><h1>Let's get connected</h1>\n<p>Save up to five home Wi-Fi networks. Pocket tests each new password before saving it.</p>\n<p id=\"session-status\" role=\"status\">Checking your setup session...</p>\n<button id=\"retry-status\" type=\"button\" class=\"secondary\">Check status</button>\n<section aria-labelledby=\"saved-heading\"><h2 id=\"saved-heading\">Saved Wi-Fi</h2>\n<p id=\"connection\" role=\"status\">Checking Pocket's Wi-Fi...</p>\n<p id=\"hermes-note\">Wi-Fi and Hermes availability are separate. If Pocket says Hermes is unreachable, check its bridge connection or pairing even when Wi-Fi is connected.</p>\n<p id=\"profile-count\">Checking saved networks...</p><ul id=\"profiles\" aria-label=\"Saved Wi-Fi networks\"></ul>\n<small id=\"storage-note\"></small></section>\n<section aria-labelledby=\"wifi-heading\"><h2 id=\"wifi-heading\">Add or update Wi-Fi</h2>\n<form id=\"wifi\" novalidate>\n<label for=\"networks\">Nearby networks - 2.4 GHz</label><select id=\"networks\"><option value=\"\">Choose a network...</option></select>\n<button id=\"scan\" type=\"button\" class=\"secondary\" disabled>Scan Wi-Fi</button>\n<p id=\"netstatus\" role=\"status\">Scan for nearby networks, or type a hidden network's name below. Open networks are unsupported.</p>\n<label for=\"ssid\">Network name</label><input id=\"ssid\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" maxlength=\"32\" aria-describedby=\"ssid-help\" placeholder=\"Select above, or type a hidden network\">\n<small id=\"ssid-help\">Use your router's Wi-Fi name, including spaces and capitals. Maximum 32 UTF-8 bytes.</small>\n<label for=\"password\">Wi-Fi password</label><input id=\"password\" type=\"password\" autocomplete=\"new-password\" autocapitalize=\"none\" spellcheck=\"false\" maxlength=\"63\" placeholder=\"Your home Wi-Fi password\">\n<label><input id=\"showpass\" type=\"checkbox\">Show password</label>\n<button id=\"join\" type=\"submit\" disabled>Test and save Wi-Fi</button>\n</form><button id=\"cancel\" type=\"button\" class=\"secondary\" disabled>Cancel Wi-Fi test</button>\n<p id=\"result\" class=\"message\" role=\"alert\" aria-live=\"assertive\"></p>\n<small>Existing Wi-Fi profiles and Hermes pairing stay saved if a test fails or is cancelled. To change a saved password, enter that network's name again.</small></section>\n<details><summary>Hermes pairing - optional</summary>\n<p id=\"pairing-state\" role=\"status\">Your existing pairing is preserved by default.</p>\n<p>Blank fields keep stored values. Only fields you enter here are updated when you tap Save Hermes pairing.</p>\n<form id=\"pairing\" novalidate>\n<label for=\"windows\">Windows bridge HTTPS address</label><input id=\"windows\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" placeholder=\"https://your-bridge.example\" maxlength=\"192\">\n<label for=\"linux\">Linux bridge HTTPS address</label><input id=\"linux\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" placeholder=\"https://your-bridge.example\" maxlength=\"192\">\n<label for=\"token\">Pocket pairing token</label><input id=\"token\" type=\"password\" autocomplete=\"new-password\" autocapitalize=\"none\" spellcheck=\"false\" maxlength=\"128\">\n<label for=\"ca\">Bridge CA certificate - optional</label><textarea id=\"ca\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" maxlength=\"2048\" rows=\"4\"></textarea>\n<small>Use only your dedicated Pocket pairing token. Saved pairing values are never shown on this page.</small>\n<button id=\"pair-save\" type=\"submit\" disabled>Save Hermes pairing</button>\n<p id=\"pair-result\" class=\"message\" role=\"alert\" aria-live=\"assertive\"></p></form></details>\n<footer><small>The owner opens this secure setup hotspot for five minutes. Keep your phone on Pocket's hotspot while using this page. If setup expires, hold OK on Pocket to reopen it. When finished, reconnect your phone to your normal Wi-Fi.</small></footer></main>\n<script>\n'use strict';\nconst $=id=>document.getElementById(id);\nconst byteLength=value=>new TextEncoder().encode(value).length;\nconst pairingFields=['windows','linux','token','ca'];\nlet snapshot=null,reachable=false,expired=false,closed=false,statusBusy=false,actionBusy=false,pairBusy=false;\nlet pollTimer=null,pending=null,scanPending=null,profileSignature='',networkSignature='',profileButtons=[],statusEpoch=0;\nconst controllers=new Set();\n\nfunction validateWifi(body){\n if(!body.ssid||byteLength(body.ssid)>32)return 'Enter a network name of 1-32 UTF-8 bytes.';\n if(byteLength(body.password)<8||byteLength(body.password)>63)return 'Wi-Fi password must be 8-63 UTF-8 bytes. Enter your home router password.';\n return '';\n}\nfunction validatePairing(body){\n for(const key of ['windows','linux'])if(body[key]&&(byteLength(body[key])>192||!/^https:\\/\\/[^\\s@?#]+$/.test(body[key])))return 'Use an HTTPS bridge address of at most 192 bytes, or leave that field blank to keep it.';\n if(body.token&&(body.token.length<32||body.token.length>128||!/^[\\x21-\\x7e]+$/.test(body.token)))return 'Pocket pairing token must be 32-128 visible characters, or leave it blank to keep it.';\n if(byteLength(body.ca)>2048||(body.ca&&(!body.ca.startsWith('-----BEGIN CERTIFICATE-----')||!body.ca.includes('-----END CERTIFICATE-----'))))return 'Enter a valid PEM certificate of at most 2048 bytes, or leave it blank to keep it.';\n return '';\n}\nfunction clearPairing(){for(const key of pairingFields)$(key).value=''}\nfunction stopPolling(){clearTimeout(pollTimer);pollTimer=null}\nfunction expireSetup(){\n expired=true;reachable=false;stopPolling();for(const controller of controllers)controller.abort();\n $('password').value='';clearPairing();pending=null;scanPending=null;\n $('session-status').textContent='Setup expired. Hold OK on Pocket to reopen setup, then reconnect to its hotspot.';\n $('result').textContent='';$('pair-result').textContent='';updateControls();\n}\nasync function request(path,body){\n const controller=new AbortController();controllers.add(controller);\n const timer=setTimeout(()=>controller.abort(),15000);\n const options={headers:{'X-Pocket-Setup':document.querySelector('meta[name=\"pocket-nonce\"]').content},cache:'no-store',signal:controller.signal};\n if(body!==undefined){options.method='POST';options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}\n try{const result=await fetch(path,options);if(result.status===403)expireSetup();return result}\n finally{clearTimeout(timer);controllers.delete(controller)}\n}\nfunction updateControls(){\n const blocked=closed||expired||!reachable||actionBusy||pairBusy;\n const running=!!pending||!!snapshot&&(snapshot.join_result===1||snapshot.connection_busy===true);\n const scanning=!!scanPending||!!snapshot&&snapshot.scan_state===1;\n const writable=!!snapshot&&snapshot.store_writable;\n $('join').disabled=blocked||running||scanning||!writable;\n $('scan').disabled=blocked||running||scanning;\n $('pair-save').disabled=blocked||running||scanning||!writable;\n $('cancel').disabled=blocked||!running||!!snapshot&&snapshot.connection_busy===true&&snapshot.join_result!==1||!!pending&&pending.kind==='cancel';\n $('retry-status').disabled=closed||expired||statusBusy;\n for(const buttons of profileButtons){\n  buttons.connect.disabled=blocked||running||scanning||buttons.connected;\n  buttons.forget.disabled=blocked||running||scanning||!writable;\n }\n}\nfunction renderProfiles(data){\n $('profile-count').textContent=data.profiles.length+' / '+data.capacity+' saved networks';\n $('storage-note').textContent=!data.store_writable?'Saved-settings storage is not writable. Saved networks can still connect; adding, forgetting, and pairing changes are unavailable.':\n  data.profiles.length>=data.capacity?'All '+data.capacity+' slots are full. Explicitly forget a network to add another. A saved network can still be retested with a new password. Nothing is automatically removed.':\n  'Pocket keeps existing profiles and Hermes pairing when you add another network. Nothing is automatically removed.';\n const signature=JSON.stringify(data.profiles);if(signature===profileSignature)return;profileSignature=signature;\n $('profiles').replaceChildren();profileButtons=[];\n if(!data.profiles.length){const empty=document.createElement('li');empty.textContent='No saved networks yet. Add one below.';$('profiles').appendChild(empty)}\n for(const profile of data.profiles){\n  const row=document.createElement('li'),name=document.createElement('strong'),note=document.createElement('small'),actions=document.createElement('div');\n  name.textContent=profile.ssid;note.textContent=profile.connected?'Connected now':'Saved on Pocket';actions.className='actions';\n  const connect=document.createElement('button'),forget=document.createElement('button');\n  connect.type=forget.type='button';connect.textContent=profile.connected?'Connected':'Connect';forget.textContent='Forget';\n  connect.className=forget.className='secondary';connect.setAttribute('aria-label','Connect to '+profile.ssid);forget.setAttribute('aria-label','Forget '+profile.ssid);\n  connect.addEventListener('click',()=>{if(!connect.disabled)return queueWifi('connect',{ssid:profile.ssid})});\n  forget.addEventListener('click',()=>{if(!forget.disabled&&window.confirm('Forget \"'+profile.ssid+'\" from Pocket? Its saved password will be removed. Hermes pairing will be kept.'))return queueWifi('forget',{ssid:profile.ssid})});\n  actions.appendChild(connect);actions.appendChild(forget);row.appendChild(name);row.appendChild(note);row.appendChild(actions);$('profiles').appendChild(row);\n  profileButtons.push({connect,forget,connected:profile.connected});\n }\n}\nfunction renderNetworks(data){\n if(scanPending&&scanPending.operation!==null&&data.operation<scanPending.operation)return;\n if(data.scan_state===1){$('netstatus').textContent='Scanning nearby Wi-Fi...';return}\n if(data.scan_state===3){scanPending=null;$('netstatus').textContent='Scan failed. Scan again, or type your network name below.';return}\n if(data.scan_state===0){if(scanPending&&scanPending.operation===null){scanPending=null;$('netstatus').textContent='Could not confirm the scan. Scan again, or type your network name below.'}return}\n if(data.scan_state!==2)return;\n scanPending=null;const signature=JSON.stringify(data.networks);if(signature===networkSignature)return;networkSignature=signature;\n const list=$('networks'),selected=list.value;list.replaceChildren();const first=document.createElement('option');first.value='';first.textContent='Choose a network...';list.appendChild(first);\n for(const network of data.networks){const option=document.createElement('option');option.value=network.ssid;\n  option.textContent=network.ssid+' - '+(network.rssi>-60?'Strong':network.rssi>-75?'Fair':'Weak')+(network.open?' - Open network unsupported':'');\n  option.disabled=network.open;list.appendChild(option)}\n list.value=data.networks.some(network=>network.ssid===selected&&!network.open)?selected:'';\n $('netstatus').textContent=data.networks.length?'Select your network, then enter its password. You can also type a hidden network below.':'No networks found. Scan again, or type your network name below.';\n}\nfunction finishWifi(data){\n if(!pending&&data.join_result===1)pending={kind:'observe',operation:data.operation};\n if(!pending)return;\n if(pending.operation===null){\n  if(data.join_result===1){pending.observed=data.operation;return}\n  if(data.operation>pending.baseline||pending.observed===data.operation){pending=null;$('result').textContent='Could not confirm the requested action. Check the saved list and Wi-Fi status before trying again. No settings were automatically resubmitted.'}\n  return;\n }\n if(data.operation<pending.operation)return;\n if(data.operation!==pending.operation){pending=null;$('result').textContent='Could not confirm completion because another Wi-Fi operation started. Check the saved list and Wi-Fi status before trying again.';return}\n if(data.join_result===0)return;\n if(data.join_result===1){$('result').textContent=pending.kind==='join'?'Testing Wi-Fi before saving. Existing profiles and Hermes pairing stay saved.':\n  pending.kind==='connect'?'Connecting to saved Wi-Fi...':pending.kind==='cancel'?'Cancelling Wi-Fi test. Waiting for confirmation...':\n  pending.kind==='forget'?'Removing saved network. Waiting for confirmation...':'A Wi-Fi operation is running on Pocket. Wait for confirmation or cancel.';return}\n const kind=pending.kind;pending=null;\n const kept=' Existing saved Wi-Fi profiles and Hermes pairing were kept.';\n const failure=['The Wi-Fi test failed.','The Wi-Fi test failed.','The Wi-Fi test failed.','The Wi-Fi test failed.',\n  'Network not found. Check the name, 2.4 GHz coverage, and signal.','Wi-Fi password was rejected. Check the router password.',\n  'Wi-Fi connected without an IP address. Check your router and try again.','Wi-Fi connection failed. Check the router and try again.'];\n if(data.join_result===2)$('result').textContent=kind==='connect'?'Connected to saved Wi-Fi. Hermes pairing was kept.':\n  kind==='forget'||kind==='cancel'?'Could not confirm the requested action. Check the saved list and Wi-Fi status.':'Wi-Fi tested and saved. Hermes pairing was kept. You can add another network or finish setup.';\n else if(data.join_result===3)$('result').textContent=failure[data.connection]+kept+' Enter the password again to retry.';\n else if(data.join_result===4)$('result').textContent='Wi-Fi test cancelled.'+kept+' Check the connection status above while Pocket restores its previous Wi-Fi.';\n else if(data.join_result===5)$('result').textContent='The saved Wi-Fi list is full. Explicitly forget a network before adding another.'+kept;\n else if(data.join_result===6)$('result').textContent='Could not confirm saving the requested change. Check saved networks before retrying. Hermes pairing was kept.';\n else if(data.join_result===7)$('result').textContent='Saved network forgotten. Hermes pairing was kept.';\n}\nfunction renderStatus(data){\n snapshot=data;reachable=true;\n if(data.expires_seconds<=0){expireSetup();return}\n $('session-status').textContent='Setup hotspot closes in about '+Math.ceil(data.expires_seconds/60)+' minute(s). Keep your phone on Pocket\\'s hotspot.';\n const connection=['Wi-Fi is disconnected.','Connecting to Wi-Fi...','Getting an IP address...',\n  'Wi-Fi connected.','Wi-Fi network not found.','Wi-Fi password was rejected.','Wi-Fi has no IP address.','Wi-Fi connection failed.'];\n $('connection').textContent=data.connected?'Wi-Fi connected to '+data.ssid+'.':connection[data.connection]||'Checking Wi-Fi status...';\n if(data.connection_busy===true&&!data.connected)$('connection').textContent='Waiting for Wi-Fi to finish its current connection attempt...';\n $('pairing-state').textContent=data.pairing_saved?'Saved Hermes pairing is preserved. Blank fields keep its stored values.':'No Hermes pairing is saved yet. You can set up Wi-Fi first.';\n renderProfiles(data);renderNetworks(data);finishWifi(data);\n}\nasync function pollStatus(){\n if(expired||closed||statusBusy)return;stopPolling();statusBusy=true;updateControls();\n // Only a GET started after the queue request settles can confirm its action.\n const epoch=statusEpoch;\n try{const result=await request('/wifi/status');if(expired||closed||epoch!==statusEpoch||actionBusy)return;if(result.status!==200)throw new Error('status unavailable');\n  const data=await result.json();if(closed||expired||epoch!==statusEpoch||actionBusy)return;\n  if(!data||!Array.isArray(data.profiles)||!Array.isArray(data.networks)||data.capacity!==5||!Number.isInteger(data.operation))throw new Error('invalid status');\n  renderStatus(data);\n }catch(error){if(!expired&&!closed&&epoch===statusEpoch&&!actionBusy){reachable=false;$('session-status').textContent='Cannot reach Pocket. Reconnect to its setup hotspot, then check status. No settings will be automatically resubmitted.';\n  if(pending)$('result').textContent='Could not confirm completion of this Wi-Fi action. Pocket may still be testing or saving. Reconnect to its hotspot and check status. No settings will be automatically resubmitted.'}}\n finally{statusBusy=false;updateControls();if(!expired&&!closed)pollTimer=setTimeout(()=>pollStatus(),1500)}\n}\nasync function queueWifi(kind,body){\n if(expired||closed||!reachable||actionBusy||pairBusy)return;\n const running=!!pending||snapshot.join_result===1,scanning=!!scanPending||snapshot.scan_state===1;\n if(kind==='cancel'?!running||pending&&pending.kind==='cancel':running||scanning)return;\n if((kind==='join'||kind==='forget')&&!snapshot.store_writable)return;\n const baseline=snapshot.operation;actionBusy=true;statusEpoch++;updateControls();\n $('result').textContent=kind==='join'?'Sending Wi-Fi test request...':kind==='connect'?'Connecting to saved Wi-Fi...':kind==='forget'?'Requesting network removal...':'Requesting cancellation...';\n try{const result=await request('/wifi/'+kind,body);if(expired||closed)return;\n  if(!result.ok){$('result').textContent=(await result.text())+' Check the fields or Wi-Fi status before trying again.';return}\n  if(result.status!==202)throw new Error('acceptance uncertain');\n  const data=await result.json();if(data.accepted!==true||!Number.isInteger(data.operation))throw new Error('acceptance uncertain');\n  pending={kind,operation:data.operation};if(kind==='join')$('password').value='';\n  $('result').textContent=kind==='join'?'Testing Wi-Fi before saving. Existing profiles and Hermes pairing stay saved.':\n   kind==='connect'?'Connecting to saved Wi-Fi...':kind==='forget'?'Removing saved network. Waiting for confirmation...':'Cancelling Wi-Fi test. Waiting for confirmation...';\n }catch(error){if(!expired&&!closed){if(kind==='join')$('password').value='';pending={kind,operation:null,baseline};\n  $('result').textContent='Could not confirm whether Pocket accepted this action. Check status or cancel before trying again. No settings will be automatically resubmitted.'}}\n finally{actionBusy=false;statusEpoch++;updateControls()}\n}\n$('showpass').addEventListener('change',()=>{$('password').type=$('showpass').checked?'text':'password'});\n$('networks').addEventListener('change',()=>{\n const selected=$('networks').value;if(selected&&snapshot&&snapshot.networks.some(network=>network.ssid===selected&&!network.open)){$('ssid').value=selected;$('password').focus()}\n});\n$('scan').addEventListener('click',async()=>{\n if($('scan').disabled)return;actionBusy=true;updateControls();$('netstatus').textContent='Scanning nearby Wi-Fi...';\n try{const result=await request('/networks');if(expired||closed)return;\n  if(!result.ok){$('netstatus').textContent=(await result.text())+' You can type your network name below.';return}\n  if(result.status!==202)throw new Error('scan uncertain');const data=await result.json();\n  if(data.accepted!==true||!Number.isInteger(data.operation))throw new Error('scan uncertain');scanPending={operation:data.operation};networkSignature='';\n }catch(error){if(!expired&&!closed){scanPending={operation:null};$('netstatus').textContent='Could not confirm the scan. Check status, or type your network name below.'}}\n finally{actionBusy=false;updateControls()}\n});\n$('wifi').addEventListener('submit',event=>{\n event.preventDefault();if($('join').disabled)return;const body={ssid:$('ssid').value,password:$('password').value};const error=validateWifi(body);\n if(error){$('result').textContent=error;return}\n if(snapshot.profiles.length>=snapshot.capacity&&!snapshot.profiles.some(profile=>profile.ssid===body.ssid)){$('result').textContent='The saved Wi-Fi list is full. Explicitly forget a network before adding another. Nothing was removed.';return}\n return queueWifi('join',body);\n});\n$('cancel').addEventListener('click',()=>{if(!$('cancel').disabled)return queueWifi('cancel',{})});\n$('retry-status').addEventListener('click',()=>{if(!$('retry-status').disabled)return pollStatus()});\n$('pairing').addEventListener('submit',async event=>{\n event.preventDefault();if($('pair-save').disabled)return;const body={};for(const key of pairingFields)body[key]=$(key).value;\n const error=validatePairing(body);if(error){$('pair-result').textContent=error;return}\n if(pairingFields.every(key=>!body[key])){$('pair-result').textContent='Existing Hermes pairing kept unchanged. Enter a field only when you want to update it.';return}\n pairBusy=true;updateControls();$('pair-result').textContent='Saving Hermes pairing...';\n try{const result=await request('/pairing',body);if(expired||closed)return;\n  if(!result.ok){$('pair-result').textContent=(await result.text())+' Check the optional fields before trying again.';return}\n  if(result.status!==200)throw new Error('pairing uncertain');clearPairing();$('pair-result').textContent='Hermes pairing saved. Fields left blank kept their stored values.';\n }catch(error){if(!expired&&!closed){clearPairing();$('pair-result').textContent='Could not confirm saving Hermes pairing. Check Pocket before entering these values again. No pairing values will be automatically resubmitted.'}}\n finally{pairBusy=false;updateControls()}\n});\nwindow.addEventListener('pagehide',()=>{closed=true;stopPolling();for(const controller of controllers)controller.abort();$('password').value='';clearPairing();updateControls()});\nwindow.addEventListener('pageshow',()=>{if(closed&&!expired){closed=false;reachable=false;return pollStatus()}});\nupdateControls();pollStatus();\n</script></html>\n";
